Scripts.OnClick:
if this:GetChecked() then
  FontFlagsOutline:SetChecked(0);
  if FontFlagsMonochrome:GetChecked() then
    HotkeySettings.font.flags = "THICKOUTLINE,Monochrome";
  else
    HotkeySettings.font.flags = "THICKOUTLINE";
  end
else
  if FontFlagsMonochrome:GetChecked() then
    HotkeySettings.font.flags = "Monochrome";
  else
    HotkeySettings.font.flags = nil;
  end
end
User_ActionButton_UpdateHotkeys(VehicleMenuBarActionButton6,"COMMAND");

Scripts.OnShow:
if HotkeySettings.font.flags and string.match(HotkeySettings.font.flags,"THICKOUTLINE") then
  this:SetChecked(1);
else
  this:SetChecked(0);
end

Scripts.OnClick:
if this:GetChecked() then
  FontFlagsThickoutline:SetChecked(0);
  if FontFlagsMonochrome:GetChecked() then
    HotkeySettings.font.flags = "OUTLINE,Monochrome";
  else
    HotkeySettings.font.flags = "OUTLINE";
  end
else
  if FontFlagsMonochrome:GetChecked() then
    HotkeySettings.font.flags = "Monochrome";
  else
    HotkeySettings.font.flags = nil;
  end
end
User_ActionButton_UpdateHotkeys(VehicleMenuBarActionButton6,"COMMAND");

Scripts.OnShow:
if HotkeySettings.font.flags and string.match(HotkeySettings.font.flags,"^OUTLINE") then
  this:SetChecked(1);
else
  this:SetChecked(0);
end

if HotkeySettings.font.flags and string.match(HotkeySettings.font.flags,"MONOCHROME") then
  this:SetChecked(1);
else
  this:SetChecked(0);
end

Scripts.OnClick:
if this:GetChecked() then
  if FontFlagsThickoutline:GetChecked() then
    HotkeySettings.font.flags = "THICKOUTLINE,Monochrome";
  elseif FontFlagsOutline:GetChecked() then
    HotkeySettings.font.flags = "OUTLINE,Monochrome";
  else
    HotkeySettings.font.flags = "Monochrome";
  end
else
  if FontFlagsThickoutline:GetChecked() then
    HotkeySettings.font.flags = "THICKOUTLINE";
  elseif FontFlagsOutline:GetChecked() then
    HotkeySettings.font.flags = "OUTLINE";
  else
    HotkeySettings.font.flags = nil;
  end
end
User_ActionButton_UpdateHotkeys(VehicleMenuBarActionButton6,"COMMAND");

